{
  "name": "utt-opencode",
  "version": "0.1.1",
  "type": "module",
  "description": "OpenCode CLI plugin: dictate into the prompt with utt, the words appearing as you speak.",
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "utt",
    "dictation",
    "speech-to-text",
    "transcription",
    "macos"
  ],
  "homepage": "https://github.com/doublej/utt/tree/main/opencode#readme",
  "bugs": "https://github.com/doublej/utt/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/doublej/utt.git",
    "directory": "opencode"
  },
  "os": [
    "darwin"
  ],
  "exports": {
    "./tui": "./dist/tui.js",
    "./package.json": "./package.json"
  },
  "files": [
    "LICENSE",
    "dist"
  ],
  "scripts": {
    "build": "bun build.ts",
    "prepack": "bun build.ts",
    "check": "tsc --noEmit",
    "test": "bun test"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.0.31",
    "@opentui/core": ">=0.5.17",
    "@opentui/solid": ">=0.5.17",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    },
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode/plugin": "2.0.31",
    "@opencode/theme": "2.0.31",
    "@opentui/core": "0.5.17",
    "@opentui/solid": "0.5.17",
    "bun-types": "^1.3.0",
    "solid-js": "^1.9.17",
    "typescript": "^5.6.0"
  }
}
